if ($_SERVER['REQUEST_METHOD'] === 'POST') {  $otp = trim($_POST['otp'] ?? '');  if (empty($otp)) {  $error = "Please enter the 6-digit OTP.";  } elseif (strlen($otp) !== 6 || !is_numeric($otp)) {  $error = "Please enter a valid 6-digit OTP.";  } else {  try {  // DEBUG: Log what we're searching for  error_log("=== OTP DEBUG ===");  error_log("Searching for OTP: {$otp}");  error_log("User ID: {$user_id}");  error_log("Token Type: login");  // First, check if ANY token exists for this user  $debug_stmt = $pdo->prepare("SELECT * FROM password_reset_tokens WHERE user_id = ? ORDER BY id DESC LIMIT 1");  $debug_stmt->execute([$user_id]);  $debug_token = $debug_stmt->fetch(PDO::FETCH_ASSOC);  error_log("Latest token for user: " . print_r($debug_token, true));  $stmt = $pdo->prepare("  SELECT prt.token, prt.expires_at, prt.is_used  FROM password_reset_tokens prt  WHERE prt.token = ? AND prt.token_type = 'login' AND prt.user_id = ?  LIMIT 1  ");  $stmt->execute([$otp, $user_id]);  $token_data = $stmt->fetch(PDO::FETCH_ASSOC);  error_log("Token data found: " . print_r($token_data, true));  if (!$token_data) {  // Try searching WITHOUT token_type filter to see if token exists at all  $debug2 = $pdo->prepare("SELECT * FROM password_reset_tokens WHERE token = ? AND user_id = ?");  $debug2->execute([$otp, $user_id]);  $any_token = $debug2->fetch(PDO::FETCH_ASSOC);  if ($any_token) {  error_log("Token EXISTS but with different type: " . $any_token['token_type']);  $error = "Invalid OTP. Token type mismatch. Expected 'login', found '{$any_token['token_type']}'";  } else {  error_log("Token does NOT exist in database at all");  $error = "Invalid OTP. Please check the code and try again.";  }  } elseif (strtotime($token_data['expires_at']) < time()) {  $error = "OTP has expired. Please login again.";  // Clean up expired token  $pdo->prepare("DELETE FROM password_reset_tokens WHERE user_id = ? AND token_type = 'login'")->execute([$user_id]);  } else {  // OTP is valid! Proceed with full login  // Clear the token  $pdo->prepare("DELETE FROM password_reset_tokens WHERE user_id = ? AND token_type = 'login'")->execute([$user_id]);  // Update last login  try {  // Remove old last-login update that used wrong column; update updated_at instead  $pdo->prepare("UPDATE users SET updated_at = NOW() WHERE `{$s_uid}` = ?")->execute([$user['user_id']]);  } catch (Exception $e) { /* ignore */ }  // Normal login success session  unset($user['password_hash']); // strip sensitive data  $_SESSION['user']  = $user;  $_SESSION['user_id'] = $user['user_id'];  $_SESSION['role']  = $user['role'];  unset($_SESSION['temp_2fa_user_id']);  unset($_SESSION['temp_2fa_login_type']);  try {  // Check if activity_logs table exists before inserting  $tables = $pdo->query("SHOW TABLES LIKE 'activity_logs'")->fetchAll();  if (!empty($tables)) {  $logStmt = $pdo->prepare("INSERT INTO activity_logs (user_id, action, details, ip_address) VALUES (?, 'Login', ?, ?)");  $logStmt->execute([$user['user_id'], "User logged in via {$login_type} (2FA Verified)", $_SERVER['REMOTE_ADDR']]);  }  $tables = $pdo->query("SHOW TABLES LIKE 'audit_logs'")->fetchAll();  if (!empty($tables)) {  $login_name  = $user['first_name'] ?? $user['username'] ?? 'Unknown';  $login_role  = ucfirst(strtolower($user['role'] ?? 'staff'));  $login_detail = "{$login_name} ({$login_role}) logged in via {$login_type} (2FA Verified)";  $auditStmt = $pdo->prepare("INSERT INTO audit_logs (user_id, log_type, action_type, action_details, entity_type, entity_id, status, ip_address, user_agent, created_at) VALUES (?, 'user', 'Login', ?, 'users', ?, 'Success', ?, ?, NOW())");  $auditStmt->execute([  $user['user_id'],  $login_detail,  $user['user_id'],  $_SERVER['REMOTE_ADDR'] ?? null,  $_SERVER['HTTP_USER_AGENT'] ?? null,  ]);  }  } catch (Exception $e) { /* Fail silently if logs table missing */ }  // Auto Clock In for staff roles on login  $role = role_key($user['role'] ?? '');  $staff_roles = ['staff', 'cashier', 'pump_attendant'];  $login_time = date('H:i:s');  $auto_shift_key = ($login_time >= '06:00:00' && $login_time < '14:00:00') ? 'first' : 'second';  $auto_shift_name = $auto_shift_key === 'first'  ? 'First Shift: 6:00 AM – 2:00 PM'  : 'Second Shift: 2:00 PM – 12:00 Midnight';  if (in_array($role, $staff_roles)) {  try {  $station_id = $user['station_id'] ?? null;  // Only clock in if not already clocked in  $check = $pdo->prepare("SELECT id, shift_period, shift_name FROM labor_sessions WHERE user_id = ? AND end_time IS NULL ORDER BY start_time DESC LIMIT 1");  $check->execute([$user['user_id']]);  $existing_session = $check->fetch(PDO::FETCH_ASSOC);  if ($existing_session && $station_id) {  $auto_shift_key = $existing_session['shift_period'];  $auto_shift_name = $existing_session['shift_name'];  } elseif ($station_id) {  // Check the user's assigned shift in the profile first  $user_assigned_shift = strtolower(trim((string)($user['assigned_shift'] ?? '')));  if (strpos($user_assigned_shift, 'shift 1') !== false || strpos($user_assigned_shift, '1') !== false || $user_assigned_shift === 'first') {  $auto_shift_key = 'first';  } elseif (strpos($user_assigned_shift, 'shift 2') !== false || strpos($user_assigned_shift, '2') !== false || $user_assigned_shift === 'second') {  $auto_shift_key = 'second';  }  // Try to load exact DB record for consistent naming  $sp = $pdo->prepare("SELECT shift_key, shift_name FROM shift_periods WHERE shift_key = ? AND is_active = 1 LIMIT 1");  $sp->execute([$auto_shift_key]);  $shift = $sp->fetch(PDO::FETCH_ASSOC);  // Hard fallback if table is empty or record missing  if (!$shift) {  $shift = $auto_shift_key === 'first'  ? ['shift_key' => 'first',  'shift_name' => 'First Shift: 6:00 AM – 2:00 PM']  : ['shift_key' => 'second', 'shift_name' => 'Second Shift: 2:00 PM – 12:00 Midnight'];  }  $auto_shift_key = $shift['shift_key'];  $auto_shift_name = $shift['shift_name'];  $pdo->prepare(  "INSERT INTO labor_sessions (user_id, station_id, start_time, shift_period, shift_name)  VALUES (?, ?, NOW(), ?, ?)"  )->execute([$user['user_id'], $station_id, $auto_shift_key, $auto_shift_name]);  $tables = $pdo->query("SHOW TABLES LIKE 'activity_logs'")->fetchAll();  if (!empty($tables)) {  $pdo->prepare("INSERT INTO activity_logs (user_id, action, details, ip_address) VALUES (?, 'Clock In', ?, ?)")  ->execute([$user['user_id'], "Auto clock-in on login - Station {$station_id} - {$auto_shift_name}", $_SERVER['REMOTE_ADDR'] ?? '0.0.0.0']);  }  }  } catch (Exception $e) { /* Fail silently, do not block login */ }  }  // Store detected shift in session so dashboards & pages can reference it  $_SESSION['current_shift_key']  = $auto_shift_key;  $_SESSION['current_shift_label'] = $auto_shift_name;  // RBAC Redirect Logic  if ($role === 'superadmin') {  header("Location: super_admin_dashboard.php");  } elseif ($role === 'admin') {  header("Location: admin_dashboard.php");  } elseif ($role === 'manager') {  header("Location: manager_dashboard.php");  } else {  header("Location: staff_dashboard.php");  }  exit;  }  } catch (PDOException $e) {  error_log("OTP validation error: " . $e->getMessage());  $error = "System error. Please try again later.";  }  }
