ition: color .2s, text-shadow .2s;  display: flex;  align-items: center;  gap: 6px;  }  .link-item:hover {  color: #ffffff;  text-shadow: 0 0 12px rgba(255,255,255,.6);  }  .timer-text {  text-align: center;  font-size: 13px;  color: rgba(255,255,255,.7);  margin-top: 15px;  font-weight: 500;  }  @media (max-width: 540px) {  .login-wrap { padding: 0 12px; }  .login-card  { padding: 38px 28px 32px; }  }  </style>
