oken_type']; ?>' but verify_login_otp expects 'login'  </div>  <?php endif; ?>  </div>  <?php if (!empty($debug_info['all_tokens'])): ?>  <details style="margin-top:8px;">  <summary style="cursor:pointer; color:#fbbf24;">Show All Recent Tokens</summary>  <div style="margin-top:8px; font-size:11px;">  <?php foreach ($debug_info['all_tokens'] as $idx => $t): ?>  <div style="background:rgba(0,0,0,0.2); padding:6px; border-radius:4px; margin:4px 0;">  <?php echo ($idx + 1); ?>. Token: <strong><?php echo $t['token']; ?></strong> |  Type: <strong><?php echo $t['token_type']; ?></strong> |  Used: <?php echo $t['is_used'] ? 'Yes' : 'No'; ?> |  Expires: <?php echo $t['expires_at']; ?>  </div>  <?php endforeach; ?>  </div>  </details>  <?php endif; ?>  <span style="display:block; font-size:11px; opacity:0.7; margin-top:8px;">  Configure Semaphore in config/sms_config.php to send real SMS.  </span>  </div>  </div>  <?php endif; ?>  <form action="" method="POST" id="otpForm">  <div class="field-group">  <div class="input-wrap">  <i class="fas fa-key input-icon"></i>  <input type="text"  name="otp"  class="field-input"  placeholder="------"  maxlength="6"  autocomplete="one-time-code"  inputmode="numeric"  pattern="\d{6}"  required>  </div>  </div>  <button type="submit" class="btn">  Verify &amp; Login <i class="fas fa-arrow-right"></i>  </button>  <div class="timer-text">  Code expires in <span id="timer">05:00</span>  </div>  </form>  <div class="links">  <a href="login.php?logout=1" class="link-item">  <i class="fas fa-arrow-left"></i> Back to Login  </a>  </div>  </div>  </div>  <script>  // Simple countdown timer (5 minutes)  let timeLeft = 300;  const timerEl = document.getElementById('timer');  const countdown = setInterval(() => {  if (timeLeft <= 0) {  clearInterval(countdown);  timerEl.textContent = "Expired";  timerEl.style.color = "#ffb3b3";  } else {  let m = Math.floor(timeLeft / 60);  let s = timeLeft % 60;  timerEl.textContent = `${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}`;  timeLeft--;  }  }, 1000);  </script>
